'use strict';
// Extend the crown's baked material language to the remaining architecture.
// Called AFTER crown_surfaces: its authored island roles stay authoritative.
//
// THE WAR DAMAGE PASS phase 2, build B (docs/205 s7b): at every break the broken
// pieces, the lip landing and the core face holding the blast crater wear the
// SCORCHED twin of their role (`<role>_scorched`, the same tint and class on the
// kit's burned tile: tools/war_damage/make_scorch.py). Which labels, and whether
// the whole brush or one face (the crater's), comes from art/war_damage/scorch.json
// (GENERATED by tools/war_damage/layout.js from the breaks' own random streams).
const fs = require('fs'), path = require('path');
const kit = require('./crown_materials.json');
const legacy = require('../tod_black_materials.json');
const C = require('../convex_brush');
const SCORCH_PATH = path.join(__dirname, '..', '..', 'art', 'war_damage', 'scorch.json');
const SCORCH = fs.existsSync(SCORCH_PATH) ? JSON.parse(fs.readFileSync(SCORCH_PATH, 'utf8')).labels : {};
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

function scorched(role, label) {
  const twin = role + '_scorched';
  if (!kit.materials[twin]) throw Error(`TOWER ART: no scorched twin ${twin} for ${label} (add it to crown_materials.json)`);
  return twin;
}

function apply(label, text) {
  let changed = 0, burned = 0;
  const burn = SCORCH[label];
  text = text.replace(/(\(\s*([^)]*)\)\s*\(\s*([^)]*)\)\s*\(\s*([^)]*)\)\s+)(mwiii_vertigo_retro_synth_[a-z_]+|tod_black_[a-z_]+|tod_dark_[a-z]+|tod_door_[a-z]+|tod_hall_wall_[1-7]) ([-\d.]+) ([-\d.]+) (?=[-\d.]+ [-\d.]+ [-\d.]+ [-\d.]+ lightmap_gray)/g,
    (face, points, p1, p2, p3, name) => {
      const suffix = name.startsWith('mwiii_vertigo_retro_synth_') ? name.slice(26)
        : name.startsWith('tod_black_') ? name.slice(10) : legacy.hall_to_black[name];
      let role = kit.tower_suffixes[suffix];
      // Hall liners are architecture too. Preserve the distinct trial colors;
      // crest plaques and trial-mark emblems remain authored signage.
      if (name.startsWith('tod_hall_wall_')) role = ['tower_gold_wall','tower_green_wall','cyan','wall','bronze_wall','graphite','oxblood'][Number(name.slice(-1))-1];
      // These plain-blue solids are floors by label in the existing collision
      // contract; they should receive the same tread texture as the crown.
      if (/^(ground slab|power hall floor|tp bay floor)$/.test(label)) role = 'floor';
      if (burn) {
        // the whole piece, or only the face whose outward normal is the one given (the crater's wall face)
        const n = C.plane([p1, p2, p3].map(s => s.trim().split(/\s+/).map(Number)), name).n;
        if (burn.faces === null || dot(n, burn.faces) > 0.9) { role = scorched(role, label); burned++; }
      }
      const def = kit.materials[role];
      if (!def) throw Error(`TOWER ART: unmapped ${name} on ${label}`);
      changed++;
      return `${points}tod_cc_${role} ${def.size} ${def.size} `;
    });
  if (burn && !burned) throw Error(`TOWER ART: scorch.json names ${label} but none of its faces took the scorched twin`);
  return {text, changed, burned};
}
module.exports = {apply, SCORCH};
